INSERT INTO [dbo].[PersonCategory]
([Name],[Description]) 
VALUES
(N'1. kategorija',N'Pokretne osobe koje samostalno obavljaju životne aktivnosti poput održavanja osobne higijene, kupanja, oblačenja, obavljanja fizioloških potreba, samostalnog objedovanja, svjesni su, orijentirani i samostalno uzimaju medicinsku terapiju (osim inzulina).'),
(N'2. kategorija', N'Polupokretne osobe kojima je potrebna pomoć prilikom obavljanja osnovnih životnih aktivnosti poput kupanja, oblačenja, hranjenja, uzimanja terapije i slično. Osobe koje koriste pempas/pelenu.'),
(N'3. kategorija', N'Nepokretne osobe koje ne mogu samostalno obavljati životne aktivnosti te su im potrebne usluge kupanja, održavanja osobne higijene, hranjenja, davanja terapije, dizanja i smještanja u invalidska kolica, presvlačenja i slično. Osobe koje koriste pempas/pelenu.'),
(N'4. kategorija', N'Osobe koje boluju od demencije, Alzheimer ili ne – Alzheimer, psihički bolesnici (podrazumijeva i osobe s rijetkom pojavom bolesti).');